add_action( 'woocommerce_before_thankyou', 'perfectpixel_no_tracking_on_failed_orders', 1 );

function perfectpixel_no_tracking_on_failed_orders( $order_id ) {
	$order = wc_get_order( $order_id );
	if ( ! $order || ! $order->has_status( 'failed' ) ) {
		return;
	}
	// Remove third-party callbacks, keep WooCommerce's own order details.
	remove_all_actions( 'woocommerce_thankyou' );
	remove_all_actions( 'woocommerce_thankyou_' . $order->get_payment_method() );
	add_action( 'woocommerce_thankyou', 'woocommerce_order_details_table', 10 );
}
